/*
 * A267927  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 249" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267927
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(0) = 1; all other terms are 1 except a(1) = a(2) = a(6) = 0
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n == 0) return (seq_t)1;
    if (n == 1 || n == 2 || n == 6) return (seq_t)0;
    return (seq_t)1;
}
